467	def parse_csv(text):
468	    """解析 RFC 4180 风格 CSV，返回 (header, data_rows)。
469	
470	    支持引号包裹的字段、引号内逗号与换行、双引号转义；
471	    引号外支持 LF / CRLF / CR 换行。结构损坏时抛 FileError。
472	    """
473	    rows = []
474	    record = []
475	    field = []
476	    quoted = False
477	    started = False
478	    i = 0
479	    n = len(text)
480	    while i < n:
481	        c = text[i]
482	        if quoted:
483	            if c == '"':
484	                if i + 1 < n and text[i + 1] == '"':
485	                    field.append('"')
486	                    i += 2
487	                    continue
488	                quoted = False
489	                i += 1
490	                continue
491	            if c == "\r":
492	                # 统一字段内换行符为 LF
493	                if i + 1 < n and text[i + 1] == "\n":
494	                    i += 1
495	                field.append("\n")
496	                i += 1
497	                continue
498	            field.append(c)
499	            i += 1
500	            continue
501	        if c == '"' and not started:
502	            quoted = True
503	            started = True
504	        elif c == ",":
505	            record.append("".join(field))
506	            field = []
507	            started = False
508	        elif c in "\r\n":
509	            if c == "\r" and i + 1 < n and text[i + 1] == "\n":
510	                i += 1
511	            if not started and not record and not field:
512	                # 空白行：不作为数据记录（显式的 "" 空字段 started=True，仍会保留）
513	                i += 1
514	                continue
515	            record.append("".join(field))
516	            rows.append(record)
517	            record = []
518	            field = []
519	            started = False
520	        else:
521	            field.append(c)
522	            started = True
523	        i += 1
524	    if quoted:
525	        raise FileError("CSV 结构损坏：存在未闭合的引号")
526	    if started or field or record:
527	        record.append("".join(field))
528	        rows.append(record)
529	    if not rows:
530	        raise FileError("CSV 内容为空：缺少表头")
531	    return rows[0], rows[1:]
532	
533	
534	def check_date(value):
535	    """校验 YYYY-MM-DD 且为真实日历日期，返回 (是否合法, 错误原因)。"""
536	    match = DATE_RE.match(value)
537	    if not match:
538	        return False, "重要日期格式无效（%s）：须为 YYYY-MM-DD" % value
539	    try:
540	        datetime.date(int(match.group(1)), int(match.group(2)), int(match.group(3)))
541	    except ValueError:
542	        return False, "重要日期无效（%s）：不是真实日历日期" % value
543	    return True, None
544	
545	
546	def import_clients(database, text):
547	    """执行导入，返回响应字典；文件级错误抛 FileError。"""
548	    header, data_rows = parse_csv(text)
549	    headers = [h.strip() for h in header]
550	
551	    seen = set()
552	    duplicates = []
553	    for h in headers:
554	        if h in seen and h not in duplicates:
555	            duplicates.append(h)
556	        seen.add(h)
557	    if duplicates:
558	        raise FileError("表头重复：%s" % "、".join(repr(h) for h in duplicates))
559	    unknown = [h for h in headers if h not in ALL_COLUMNS]
560	    if unknown:
561	        raise FileError("出现未知列：%s" % "、".join(repr(h) for h in unknown))
562	    if "name" not in headers:
563	        raise FileError("缺少名称列：表头必须包含 name 列")
564	
565	    index = {h: i for i, h in enumerate(headers)}
566	    name_index = index["name"]
567	    date_index = index.get("important_date")
568	
569	    existing = {}
570	    for cid, cname in database.execute("SELECT id, name FROM clients"):
571	        existing[(cname or "").strip().casefold()] = cid
572	
573	    imported = []
574	    failures = []
575	    seen_in_file = {}
576	
577	    for row_number, raw in enumerate(data_rows, start=1):
578	        if len(raw) != len(headers):
579	            failures.append({
580	                "row": row_number,
581	                "reason": "列数不符：表头有 %d 列，该记录有 %d 列" % (len(headers), len(raw)),
582	            })
583	            continue
584	
585	        name = raw[name_index].strip()
586	        problems = []
587	        if not name:
588	            problems.append("缺少名称：name 列为空")
589	        date_value = ""
590	        if date_index is not None:
591	            date_value = raw[date_index].strip()
592	            if date_value:
593	                ok, reason = check_date(date_value)
594	                if not ok:
595	                    problems.append(reason)
596	        if problems:
597	            failures.append({"row": row_number, "reason": "；".join(problems)})
598	            continue
599	
600	        key = name.casefold()
601	        if key in existing:
602	            failures.append({
603	                "row": row_number,
604	                "reason": "名称与已有客户重复（已有客户编号 %d），未更新" % existing[key],
605	            })
606	            continue
607	        if key in seen_in_file:
608	            failures.append({
609	                "row": row_number,
610	                "reason": "名称与文件内第 %d 条记录重复" % seen_in_file[key],
611	            })
612	            continue
613	
614	        seen_in_file[key] = row_number
615	        record = {"name": name}
616	        for field_name in OPTIONAL_FIELDS:
617	            idx = index.get(field_name)
618	            value = raw[idx].strip() if idx is not None else ""
619	            record[field_name] = value or None
620	        imported.append((row_number, record))
621	
622	    saved = []
623	    for row_number, record in imported:
624	        cursor = database.execute(
625	            "INSERT INTO clients (name, source, region, industry, important_date)"
626	            " VALUES (:name, :source, :region, :industry, :important_date)",
627	            record,
628	        )
629	        saved.append({"row": row_number, "id": cursor.lastrowid, "name": record["name"]})
630	    database.commit()
631	
632	    return {
633	        "imported_count": len(saved),
634	        "failed_count": len(failures),
635	        "imported": saved,
636	        "failures": failures,
637	    }
638	
639	
640	def main():
641	    parser = argparse.ArgumentParser(description="ClientBook - 客户联系人与商机记录")
642	    commands = parser.add_subparsers(dest="command", required=True)
643	    serve = commands.add_parser("serve", help="Start the HTTP service")
644	    serve.add_argument("--host", default="127.0.0.1", help="Address to bind (default: 127.0.0.1)")
645	    serve.add_argument("--port", type=int, default=8080, help="Port to bind; 0 selects an available port")
646	    serve.add_argument("--data-dir", type=Path, default=Path("data"), help="Directory for the local SQLite database")
647	    args = parser.parse_args()
648	    if not 0 <= args.port <= 65535:
649	        parser.error("port must be between 0 and 65535")
650	    args.data_dir.mkdir(parents=True, exist_ok=True)
651	    database = sqlite3.connect(args.data_dir / "client-book.sqlite")
652	    database.execute("CREATE TABLE IF NOT EXISTS clients (id INTEGER PRIMARY KEY, name TEXT NOT NULL)")
653	    columns = {row[1] for row in database.execute("PRAGMA table_info(clients)")}
654	    for field_name in OPTIONAL_FIELDS:
655	        if field_name not in columns:
656	            database.execute("ALTER TABLE clients ADD COLUMN %s TEXT" % field_name)
657	    database.commit()
658	
659	    class Handler(BaseHTTPRequestHandler):
660	        def respond(self, status, value, *, html=False, allow=None):
661	            payload = value.encode("utf8") if html else json.dumps(value, ensure_ascii=False).encode("utf8")
662	            self.send_response(status)
663	            self.send_header("Content-Type", "text/html; charset=utf-8" if html else "application/json; charset=utf-8")
664	            self.send_header("Content-Length", str(len(payload)))
665	            if status == 405:
666	                self.send_header("Allow", allow or "GET")
667	            self.end_headers()
668	            self.wfile.write(payload)
669	
670	        def handle_import(self):
671	            try:
672	                length = int(self.headers.get("Content-Length") or 0)
673	            except ValueError:
674	                length = 0
675	            if length > MAX_BODY:
676	                self.respond(400, {"error": "文件过大：超过 %d 字节上限" % MAX_BODY})
677	                return
678	            raw_body = self.rfile.read(length) if length > 0 else b""
679	            try:
680	                text = raw_body.decode("utf-8-sig")
681	            except UnicodeDecodeError:
682	                self.respond(400, {"error": "编码错误：文件不是有效的 UTF-8 文本"})
683	                return
684	            try:
685	                result = import_clients(database, text)
686	            except FileError as exc:
687	                database.rollback()
688	                self.respond(400, {"error": str(exc)})
689	                return
690	            self.respond(200, result)
691	
692	        def handle_batch_update(self):
693	            try:
694	                length = int(self.headers.get("Content-Length") or 0)
695	            except ValueError:
696	                length = 0
697	            if length > MAX_BODY:
698	                self.respond(400, {"error": "请求体过大：超过 %d 字节上限" % MAX_BODY})
699	                return
700	            raw_body = self.rfile.read(length) if length > 0 else b""
701	            try:
702	                payload = json.loads(raw_body.decode("utf-8"))
703	            except (UnicodeDecodeError, json.JSONDecodeError):
704	                self.respond(400, {"error": "请求体不是有效的 UTF-8 JSON 对象"})
705	                return
706	            try:
707	                result = batch_update_clients(database, payload)
708	            except BatchUpdateError as exc:
709	                database.rollback()
710	                self.respond(400, {"error": str(exc)})
711	                return
712	            self.respond(200, result)
713	
714	        def route(self):
715	            location = urlsplit(self.path).path
716	            if location not in (
717	                "/", "/health", "/api/clients",
718	                "/api/clients/import", "/api/clients/batch-update",
719	            ):
720	                self.respond(404, {"error": "not found"})
721	                return
722	            if location == "/api/clients/import":
723	                if self.command != "POST":
724	                    self.respond(405, {"error": "method not allowed"}, allow="POST")
725	                    return
726	                self.handle_import()
727	                return
728	            if location == "/api/clients/batch-update":
729	                if self.command != "POST":
730	                    self.respond(405, {"error": "method not allowed"}, allow="POST")
731	                    return
732	                self.handle_batch_update()
733	                return
734	            if self.command != "GET":
735	                self.respond(405, {"error": "method not allowed"}, allow="GET")
736	                return
737	            if location == "/":
738	                self.respond(200, PAGE, html=True)
739	            elif location == "/health":
740	                self.respond(200, {"status": "ok", "product": PRODUCT})
741	            else:
742	                records = [
743	                    {
744	                        "id": row[0],
745	                        "name": row[1],
746	                        "source": row[2],
747	                        "region": row[3],
748	                        "industry": row[4],
749	                        "important_date": row[5],
750	                    }
751	                    for row in database.execute(
752	                        "SELECT id, name, source, region, industry, important_date FROM clients ORDER BY id"
753	                    )
754	                ]
755	                self.respond(200, {RESOURCE: records})
756	
757	        do_GET = do_POST = do_PUT = do_PATCH = do_DELETE = do_HEAD = do_OPTIONS = route
758	
759	    def stop(_signal, _frame):
760	        raise KeyboardInterrupt
761	
762	    signal.signal(signal.SIGTERM, stop)
763	    server = None
764	    try:
765	        server = HTTPServer((args.host, args.port), Handler)
766	        host, port = server.server_address[:2]
767	        address = f"[{host}]" if ":" in host else host
768	        print(f"{PRODUCT} listening on http://{address}:{port}", flush=True)
769	        server.serve_forever()
770	    except KeyboardInterrupt:
771	        pass
772	    finally:
773	        if server is not None:
774	            server.server_close()
775	        database.close()
776	
777	
778	if __name__ == "__main__":
779	    main()
