    const data = await res.json();
    if (!res.ok) {
      showBatchReport('<div class="banner bad">本次修改已全部拒绝，客户资料保持原样。<br>原因：' +
        esc(data.error || "未知错误") + "</div>");
      return;
    }
    const count = data.updated_count;
